from typing import List


class Solution:
    def countValidSelections(self, nums: List[int]) -> int:
        total = sum(nums)
        left = 0
        result = 0
        prev = None
        for x in nums:
            left += x
            if x != 0 or prev == 0:
                prev = x
                continue
            prev = x
            right = total - left
            if left == right:
                result += 2
            elif abs(left - right) == 1:
                result += 1
        return result
